// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint64 t1, uint64 t2, address actor) public {
        vm.assume(t2 < t1);
        vm.assume(actor != address(c) && actor != address(this));

        // First call at time t1: succeeds, records pastBlockTime = t1
        vm.warp(t1);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);
        assertEq(c.pastBlockTime(), t1);

        // Second call at an earlier time t2: must revert WITHOUT changing pastBlockTime
        vm.warp(t2);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        assertFalse(ok2);

        // General rule: a reverted call never persists state changes.
        assertTrue(c.pastBlockTime() == t1);
    }
}
